	/** 
	 * jumpstart the process by instantiating2 Endorsement
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		endorsementId = EndorsementService.getEndorsementInstance()
		.createEndorsement( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		EndorsementService.getEndorsementInstance()
				.createEndorsement( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.endorsementSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Endorsement : " + successValue.getEndorsementId());
							  if (successValue.getEndorsementId().equals(endorsementId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfEndorsementList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Endorsement test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on endorsement consumed")
					);
			subscriber.endorsementSubscribe( endorsementId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Endorsement : " + successValue.getEndorsementId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfEndorsementList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on endorsement for endorsementId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Endorsement. 
	 */
	protected Endorsement read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Endorsement" );

		Endorsement entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Endorsement with primary key" );
		msg.append( endorsementId );
		
		EndorsementFetchOneSummary fetchOneSummary = new EndorsementFetchOneSummary( endorsementId );

		try {
			entity = EndorsementService.getEndorsementInstance().getEndorsement( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Endorsement " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Endorsement.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Endorsement." );

		StringBuilder msg = new StringBuilder( "Failed to update a Endorsement : " );        
		Endorsement entity = read();
		UpdateEndorsementCommand command = generateUpdateCommand();
		command.setEndorsementId(entity.getEndorsementId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Endorsement." );

			// for use later on...
			endorsementId = entity.getEndorsementId();

			EndorsementService proxy = EndorsementService.getEndorsementInstance();  

			proxy.updateEndorsement( command ).get();

			LOGGER.info( "-- Successfully saved Endorsement - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + endorsementId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Endorsement.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Endorsement." );

		Endorsement entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Endorsement with id " + endorsementId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Endorsement with id " + endorsementId );

			throw e;
		}

		try{
			EndorsementService.getEndorsementInstance().delete( new DeleteEndorsementCommand( entity.getEndorsementId() ) ).get();
			LOGGER.info( "-- Successfully deleted Endorsement with id " + endorsementId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Endorsement with id " + endorsementId );

			throw e;
		}
	}

	/**
	 * get all Endorsements.
	 */
	protected List<Endorsement> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Endorsements:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Endorsement : " );        
		List<Endorsement> collection  = new ArrayList<>();

		try {
			// call the static get method on the EndorsementService
			collection = EndorsementService.getEndorsementInstance().getAllEndorsement();
			assertNotNull( collection, "An Empty collection of Endorsement was incorrectly returned.");
			
			// Now print out the values
			Endorsement entity = null;            
			Iterator<Endorsement> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getEndorsementId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

